from ortools.linear_solver import pywraplp
import json

def solve_distribution_network():
    solver = pywraplp.Solver.CreateSolver("SCIP")
    if not solver:
        return

    centers = ['A', 'B', 'C']
    stores = [1, 2, 3, 4, 5, 6, 7]

    setup_cost = {'A': 1200, 'B': 650, 'C': 1850}

    capacity = {'A': 180, 'B': 95, 'C': 220}

    demand = {1: 75, 2: 42, 3: 88, 4: 56, 5: 63, 6: 91, 7: 37}

    trans_cost = {
        'A': {1: 23, 2: 15, 3: 9, 4: 28, 5: 17, 6: 32, 7: 13},
        'B': {1: 8, 2: 27, 3: 33, 4: 14, 5: 25, 6: 11, 7: 29},
        'C': {1: 31, 2: 12, 3: 19, 4: 22, 5: 8, 6: 26, 7: 16}
    }

    open_var = {}
    for i in centers:
        open_var[i] = solver.BoolVar(f"open_{i}")

    ship = {}
    for i in centers:
        ship[i] = {}
        for j in stores:
            ship[i][j] = solver.NumVar(0, solver.infinity(), f"ship_{i}_{j}")

    for j in stores:
        solver.Add(sum(ship[i][j] for i in centers) == demand[j])

    for i in centers:
        solver.Add(sum(ship[i][j] for j in stores) <= capacity[i] * open_var[i])

    setup_cost_expr = sum(setup_cost[i] * open_var[i] for i in centers)
    trans_cost_expr = sum(trans_cost[i][j] * ship[i][j] for i in centers for j in stores)

    solver.Minimize(setup_cost_expr + trans_cost_expr)

    status = solver.Solve()

    if status == pywraplp.Solver.OPTIMAL:
        total_cost = int(round(solver.Objective().Value()))

        center_to_index = {'A': 0, 'B': 1, 'C': 2}
        distribution_centers_open = [0, 0, 0]
        for i in centers:
            if open_var[i].solution_value() > 0.5:
                distribution_centers_open[center_to_index[i]] = 1

        allocations = []
        for j in stores:
            store_alloc = [0.0, 0.0, 0.0]
            for i in centers:
                idx = center_to_index[i]
                val = ship[i][j].solution_value()
                store_alloc[idx] = round(val, 6)
                if abs(store_alloc[idx]) < 1e-6:
                    store_alloc[idx] = 0.0
            allocations.append(store_alloc)

        print(json.dumps({
            "total_cost": total_cost,
            "distribution_centers_open": distribution_centers_open,
            "allocations": allocations
        }))

    elif status == pywraplp.Solver.INFEASIBLE:
        print(json.dumps({"error": "Problem is infeasible"}))
    elif status == pywraplp.Solver.UNBOUNDED:
        print(json.dumps({"error": "Problem is unbounded"}))
    else:
        print(json.dumps({"error": f"Solver status: {status}"}))

if __name__ == "__main__":
    solve_distribution_network()
